params.command:
$ErrorActionPreference='Continue';
Write-Output '=== HASHES ===';
Get-FileHash "$env:USERPROFILE\.mhw-local-tools\heaven-desktop-worker.py" -Algorithm SHA256 | Select-Object Path,Hash | Format-List;
Get-FileHash "$env:USERPROFILE\HeavenBridgeRepo\heaven-bridge\worker.py" -Algorithm SHA256 | Select-Object Path,Hash | Format-List;
Write-Output '=== WORKERS ===';
Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -and ($_.CommandLine -like '*heaven-desktop-worker.py*' -or $_.CommandLine -like '*heaven-bridge\worker.py*') } | Select-Object ProcessId,CreationDate,CommandLine | Format-List;
Write-Output '=== TASK ===';
try { Get-ScheduledTask -TaskName 'Heaven Local Bridge' | Select-Object TaskName,State | Format-List } catch { Write-Output ('TASK_ERR='+$_.Exception.Message) };
Write-Output '=== LOG ===';
if(Test-Path "$env:USERPROFILE\HeavenBridge\worker.log"){Get-Content "$env:USERPROFILE\HeavenBridge\worker.log" -Tail 120}
